--   dropped itemset 905  ( 5 pieces, FL-custom entries >= 56000): Breastplate of Nak'Talim's Wrath
--   kept 95 itemsets.
--
-- SIX SCHEMA FACTS the resolver honours (spec 1.3, all measured read-only):
--   1. creature_template.rank = 3 is WORLD boss, not dungeon boss - the boss predicate is rank 3 OR
--      ScriptName LIKE 'boss%' OR instance_encounters.creditEntry (creditType 0), on the BASE entry.
--   2. creature_loot_template.Reference <> 0 means the Item column is NOT an item (LootMgr.cpp:1700 vs
--      :1714) - the resolver recurses into reference_loot_template.
--   3. Difficulty clones (difficulty_entry_1/2/3) keep rank but LOSE ScriptName; slot 1 = heroic 5-man
--      / 25N raid, slot 2 = 10H, slot 3 = 25H.
--   4. Script-summoned bosses are absent from `creature` (Anub'arak, Yogg-Saron, Sindragosa, Tyrannus,
--      ...) - each pool carries an explicit supplement list of base entries.
--   5. Eye of Eternity has ZERO creature loot (Malygos lootid = 0); its gear lives in cache
--      gameobjects, which is why every pool also seeds gameobject_template.
--   6. dungeonencounter_dbc is empty on this realm - there is no DB-side map-to-encounter link, so maps
--      are attributed through `creature`.`map` plus the supplement lists.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `pdungeon_loot_pool` (
    `pool`      VARCHAR(16)       NOT NULL,            -- HC5_EPIC RAID_N RAID_HC ICC_N ICC_HC MATS
    `item`      INT UNSIGNED      NOT NULL,
    `weight`    SMALLINT UNSIGNED NOT NULL DEFAULT 100,
    `expansion` TINYINT UNSIGNED  NOT NULL DEFAULT 2,  -- 0 classic 1 tbc 2 wotlk (F1 reads it)
    `category`  VARCHAR(16)       NOT NULL DEFAULT '', -- MATS: gem cloth leather metal_stone herb elemental enchanting cooking_meat jewelcrafting
    `comment`   VARCHAR(96)       NOT NULL DEFAULT '', -- item name, ilvl (generator output, human aid)
    PRIMARY KEY (`pool`, `item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `pdungeon_loot_bonus` (   -- independent rolls, final cache only (L5)
    `id`         SMALLINT UNSIGNED NOT NULL,
    `item`       INT UNSIGNED      NOT NULL,
    `chance_bp`  INT UNSIGNED      NOT NULL,           -- 1/10000 before the room factor
    `min_count`  SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    `max_count`  SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    `min_diff`   TINYINT UNSIGNED  NOT NULL DEFAULT 1, -- run difficulty gate
    `armor_pick` TINYINT UNSIGNED  NOT NULL DEFAULT 0, -- 1: item + 0..3 by the looter's armour type (cloth leather mail plate)
    `comment`    VARCHAR(96)       NOT NULL DEFAULT '',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

